using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using Kairo.Application.DTOs;

namespace Kairo.Application.Abstractions.Persistence;

/// <summary>
/// Phase 4A: Repository abstraction for durable ingestion jobs.
/// Supports atomic enqueueing, safe concurrency-leased claiming, and terminal state tracking.
/// JobId is always a database-generated long (BIGINT IDENTITY / GENERATED BY DEFAULT AS IDENTITY).
/// </summary>
public interface IIngestionJobRepository
{
    /// <summary>
    /// Enqueues a new durable memory processing job.
    /// Returns the database-generated numeric job ID.
    /// </summary>
    Task<long> EnqueueJobAsync(
        MemoryIngestionJobRecord job,
        CancellationToken cancellationToken = default);

    /// <summary>
    /// Retrieves a job by ID scoped to the authenticated user and project.
    /// </summary>
    Task<MemoryIngestionJobRecord?> GetJobAsync(
        long jobId,
        long userId,
        long projectId,
        CancellationToken cancellationToken = default);

    /// <summary>
    /// Claims the next batch of pending or expired-lease jobs using atomic row leasing.
    /// </summary>
    Task<List<MemoryIngestionJobRecord>> ClaimNextJobsAsync(
        int batchSize,
        string workerId,
        TimeSpan leaseDuration,
        CancellationToken cancellationToken = default);

    /// <summary>
    /// Marks a job as successfully completed.
    /// </summary>
    Task<bool> CompleteJobAsync(
        long jobId,
        CancellationToken cancellationToken = default);

    /// <summary>
    /// Marks a job as successfully completed only if the caller still owns the active lease claim.
    /// Returns false if the claim was lost, expired, or the job is no longer processing.
    /// </summary>
    Task<bool> CompleteJobAsync(
        long jobId,
        string? lockOwner,
        CancellationToken cancellationToken = default);

    /// <summary>
    /// Marks a job as failed, scheduling a retry if eligible or moving to terminal Failed state.
    /// </summary>
    Task<bool> FailJobAsync(
        long jobId,
        string error,
        bool canRetry,
        TimeSpan? retryDelay = null,
        CancellationToken cancellationToken = default);

    /// <summary>
    /// Marks a job as failed, scheduling a retry if eligible or moving to terminal Failed state,
    /// only if the caller still owns the active lease claim.
    /// Returns false if the claim was lost, expired, or the job is no longer processing.
    /// </summary>
    Task<bool> FailJobAsync(
        long jobId,
        string error,
        bool canRetry,
        TimeSpan? retryDelay,
        string? lockOwner,
        CancellationToken cancellationToken = default);

    /// <summary>
    /// Marks a job as cancelled (e.g. parent memory deleted or expired before execution).
    /// </summary>
    Task<bool> CancelJobAsync(
        long jobId,
        string reason,
        CancellationToken cancellationToken = default);

    /// <summary>
    /// Marks a job as cancelled, optionally validating that the caller still owns the active claim.
    /// </summary>
    Task<bool> CancelJobAsync(
        long jobId,
        string reason,
        string? lockOwner,
        CancellationToken cancellationToken = default);

    /// <summary>
    /// Recovers expired-lease jobs that have reached their maximum attempts, atomically
    /// transitioning them to terminal Failed state so they do not remain in Processing indefinitely.
    /// </summary>
    Task<int> RecoverExhaustedJobsAsync(
        CancellationToken cancellationToken = default);

    /// <summary>
    /// Extends the lease duration of an actively owned job.
    /// Returns false if the caller no longer owns the active claim.
    /// </summary>
    Task<bool> RenewLeaseAsync(
        long jobId,
        string lockOwner,
        TimeSpan extension,
        CancellationToken cancellationToken = default);
}
